<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Shared\Security;

/**
 * Represents the identity of an authenticated or anonymous user, including
 * roles, claims, and authorization scope.
 */
class Identity implements \JsonSerializable
{
    /**
     * No authorization scope granted.
     */
    public const string AUTH_SCOPE_NONE = 'none';
    /**
     * Read-only authorization scope granted.
     */
    public const string AUTH_SCOPE_READ = 'read';
    /**
     * Read and write authorization scope granted.
     */
    public const string AUTH_SCOPE_BOTH = 'read-write';

    /**
     * Creates an anonymous identity.
     *
     * @return Identity An instance representing an anonymous user.
     */
    public static function anonymous(): Identity
    {
        return self::from(anonymous: true);
    }

    public static function from(
        bool $anonymous,
        ?string $authScope = null,
        ?string $id = null,
        ?string $name = null,
        ?string $token = null,
        ?string $issuer = null,
        ?string $tenant = null,
        ?array $roles = null,
        ?array $groups = null,
        ?array $claims = null,
        ?string $scope = null,
        ?string $email = null,
    ): Identity {
        return new Identity(
            anonymous: $anonymous,
            authScope: $authScope ?? self::AUTH_SCOPE_NONE,
            id: $id ?? '',
            name: $name ?? '',
            token: $token ?? '',
            issuer: $issuer ?? '',
            tenant: $tenant ?? '',
            roles: $roles ?? [],
            groups: $groups ?? [],
            claims: $claims ?? [],
            scope: $scope ?? '',
            email: $email ?? '',
        );
    }

    /**
     * Constructs an Identity object.
     */
    public function __construct(
        private readonly bool $anonymous,
        private readonly string $authScope,
        private readonly string $id,
        private readonly string $name,
        private readonly string $token,
        private readonly string $issuer,
        private readonly string $tenant,
        /** @var array<int, string> */
        private readonly array $roles,
        /** @var array<int, string> */
        private readonly array $groups,
        /** @var array<string, string> */
        private readonly array $claims,
        private readonly string $scope,
        private readonly string $email,
    ) {
    }

    public function isAnonymous(): bool
    {
        return $this->anonymous;
    }

    public function getAuthScope(): string
    {
        return $this->authScope;
    }

    public function getId(): string
    {
        return $this->id;
    }

    public function getUid(): string
    {
        return $this->id;
    }

    public function getName(): string
    {
        return $this->name;
    }

    public function getToken(): string
    {
        return $this->token;
    }

    public function getIssuer(): string
    {
        return $this->issuer;
    }

    public function getTenant(): string
    {
        return $this->tenant;
    }

    /** @return array<int, string> */
    public function getRoles(): array
    {
        return $this->roles;
    }

    /** @return array<int, string> */
    public function getGroups(): array
    {
        return $this->groups;
    }

    /** @return array<string, string> */
    public function getClaims(): array
    {
        return $this->claims;
    }

    public function getScope(): string
    {
        return $this->scope;
    }

    public function getEmail(): string
    {
        return $this->email;
    }

    public function jsonSerialize(): array
    {
        return [
            'anonymous' => $this->anonymous,
            'authScope' => $this->authScope,
            'id' => $this->id,
            'name' => $this->name,
            'token' => $this->token,
            'issuer' => $this->issuer,
            'tenant' => $this->tenant,
            'roles' => $this->roles,
            'groups' => $this->groups,
            'claims' => $this->claims,
            'scope' => $this->scope,
            'email' => $this->email,
        ];
    }

    /**
     * Retrieves the value of a specific claim.
     *
     * @param string $claim The name of the claim.
     * @return string|null The value of the claim if present, or null otherwise.
     */
    public function getClaim(string $claim): ?string
    {
        return isset($this->claims[$claim]) ? $this->claims[$claim] : null;
    }

    /**
     * Checks if the identity has a specific scope.
     *
     * @param string $scope The scope to check.
     * @return bool Always returns false (not yet implemented).
     */
    public function hasScope(string $scopeName): bool
    {
        if ($this->scope === '') {
            return false;
        }
        $scope = strtolower($scopeName);
        $scopes = strtolower($this->scope);
        return in_array($scope, explode(' ', $scopes), true);
    }

    /**
     * Checks if the identity has at least one of the given scope.
     *
     * @param string ...$scopes One or more roles to check.
     * @return bool True if any of the roles match; false otherwise.
     */
    public function hasAnyScope(string ...$scopes): bool
    {
        if ($this->scope === '') {
            return false;
        }
        foreach ($scopes as $scope) {
            if ($this->hasScope($scope)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if the identity has at least one of the given roles.
     *
     * @param string ...$roles One or more roles to check.
     * @return bool True if any of the roles match; false otherwise.
     */
    public function hasAnyRole(string ...$roles): bool
    {
        if (empty($this->roles)) {
            return false;
        }
        foreach ($roles as $role) {
            if ($this->hasRole($role)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if the identity has a specific role.
     *
     * @param string $role The role to check.
     * @return bool True if the role is present; false otherwise.
     */
    public function hasRole(string $roleName): bool
    {
        if (empty($this->roles)) {
            return false;
        }
        $role = strtolower($roleName);
        $roles = array_map(fn ($item) => strtolower($item), $this->roles);

        // Match exact
        if (in_array($role, $roles, true)) {
            return true;
        }

        // Wildcard prefix match: e.g. "platform:*" matches "platform:admin", "platform:support"
        if (str_ends_with($role, ':*')) {
            $prefix = substr($role, 0, -1); // keep trailing ":" (e.g. "platform:")

            foreach ($roles as $r) {
                if (str_starts_with($r, $prefix)) {
                    return true;
                }
            }
        }

        return false;
    }
}
